actions.script:
const dbFuture = ec.service.async().name("org.moqui.dev.InstanceServices.check#AppDatabase").parameter("appInstanceId", appInstanceId).callFuture()
const instFuture = ec.service.async().name("org.moqui.dev.InstanceServices.check#AppInstance").parameter("appInstanceId", appInstanceId).callFuture()
const msFuture = ec.service.async().name("org.moqui.dev.InstanceServices.check#MoquiServer").parameter("appInstanceId", appInstanceId).callFuture()

ec.context.putAll(dbFuture.get())
ec.context.putAll(instFuture.get())
ec.context.putAll(msFuture.get())

const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const restClient = ec.service.rest().method("GET").uri().host(String(appInstance.hostName)).path("status").build()

try {
    const restResponse = restClient.call()
    if (restResponse.statusCode == 200) {
        moquiConnectSuccess = true
        moquiStatusMap = restResponse.jsonObject()
    } else {
        moquiConnectSuccess = false
        ec.message.addMessage(`Server error on Moqui server: ${restResponse.getReasonPhrase()}`)
    }
} catch (e) {
    moquiConnectSuccess = false
    ec.logger.error(`Error connecting to Moqui server at ${restClient.getUri()}: ${e}`)
    ec.message.addMessage(`Error connecting to Moqui server at ${restClient.getUri()}: ${e}`)
}

connectSuccess = null
instanceCreated = false
instanceExists = null
instanceUuid = null
warnings = null

const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
if (instanceHost == null) {
    ec.message.addError(`No InstanceHost found for AppInstance ${appInstanceId}`); return;
}
const instanceImage = appInstance.findRelatedOne("image", null, null)
if (instanceImage == null) {
    ec.message.addError(`No InstanceImage found for AppInstance ${appInstanceId}`); return;
}
const instanceImageType = instanceImage.findRelatedOne("imageType", null, null)
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("POST")
dockerUri(restClient, "containers", "create").parameter("name", String(appInstance.instanceName)).build()

const hostConfigMap = {RestartPolicy: {Name: "unless-stopped"}}
const linkList = []
for (const link of appInstance.links) linkList.push(`${link.instanceName}:${link.aliasName || link.instanceName}`)
if (linkList.length) hostConfigMap.Links = linkList
const networkMode = appInstance.networkMode || instanceImageType?.defaultNetworkMode
if (networkMode) hostConfigMap.NetworkMode = networkMode

const envList = []
for (const env of appInstance.envs) if (env.envValue) envList.push(`${env.envName}=${env.envValue}`)

const bindList = []
for (const vol of appInstance.vols) if (vol.mountPoint && vol.volumeName) bindList.push(`${vol.volumeName}:${vol.mountPoint}`)
if (bindList.length) hostConfigMap.Binds = bindList

for (const hostConf of appInstance.hostConfigs) if (hostConf.hostConfigName && hostConf.hostConfigValue) {
    let hostConfigValue
    if (hostConf.type == null || hostConf.type == 'String') hostConfigValue = hostConf.hostConfigValue
    else if (hostConf.type == 'Number') hostConfigValue = toNumber(ec.l10n.parseNumber(hostConf.hostConfigValue, null))
    else throw new Error(`Unknown type '${hostConf.type}' for hostConfig`)
    hostConfigMap[hostConf.hostConfigName] = hostConfigValue
}

let jsonBody = {Image: instanceImage.imageName, Env: envList, HostConfig: hostConfigMap}
const initCommand = appInstance.initCommand || instanceImageType?.defaultInitCommand
if (initCommand) jsonBody.Cmd = initCommand

if (appInstance.jsonConfig) {
    // jsonBody over the base config, as CollectionUtilities.mergeNestedMap(base, jsonBody, false)
    const mergeNested = (base, over) => {
        for (const [key, value] of Object.entries(over)) {
            const baseValue = base[key]
            if (value != null && typeof value === "object" && !Array.isArray(value) &&
                    baseValue != null && typeof baseValue === "object" && !Array.isArray(baseValue)) {
                mergeNested(baseValue, value)
            } else if (Array.isArray(value) && Array.isArray(baseValue)) {
                for (const item of value) if (!baseValue.includes(item)) baseValue.push(item)
            } else {
                base[key] = value
            }
        }
        return base
    }
    jsonBody = mergeNested(JSON.parse(String(appInstance.jsonConfig)), jsonBody)
}

ec.logger.info(`Initializing docker container for ${appInstance.instanceName} with:\n${JSON.stringify(jsonBody)}`)
restClient.jsonObject(jsonBody)

try {
    let authTokenPass = null
    if (instanceImage.authTokenCmd) {
        try {
            // the configured command, split on spaces with no shell; its first output line is the token
            authTokenPass = ec.resource.runTokenCommand(instanceImage.authTokenCmd)
        } catch (e) {
            authTokenPass = null
            ec.logger.error(`Error connecting to Docker host in processing the auth token command: ${e}`)
            ec.message.addError(`Error connecting to Docker host: ${e}`)
        }
    } else {
        authTokenPass = instanceImage.password
    }
    // registryLocation is the registry's server address
    const jsonAuth = {username: instanceImage.username, password: authTokenPass, email: instanceImage.emailAddress,
            serveraddress: instanceImage.registryLocation}
    const authEncoded = StringUtilities.base64Encode(JSON.stringify(jsonAuth))
    const restClientImageCreate = ec.service.rest().method("POST").addHeader("X-Registry-Auth", authEncoded)
    dockerUri(restClientImageCreate, "images", "create")
            .parameters({fromImage: String(instanceImage.imageName), repo: String(instanceImage.imageName)}).build()
    restClientImageCreate.timeout(1000)

    const restResponseImageCreate = restClientImageCreate.call()
    if (restResponseImageCreate.statusCode != 200) {
        ec.message.addMessage(`Error Image-pull-fail problem image not-exists either or credential is wrong (${restResponseImageCreate.statusCode}): ${restResponseImageCreate.getReasonPhrase()}`)
    }
} catch (e) {
    connectSuccess = false
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

try {
    const restResponse = restClient.call()
    connectSuccess = true

    if (restResponse.statusCode == 201) {
        instanceCreated = true
        instanceExists = true

        const jsonObj = restResponse.jsonObject()
        instanceUuid = jsonObj.Id
        warnings = jsonObj.Warnings

        if (instanceUuid) {
            appInstance.instanceUuid = instanceUuid
            appInstance.update()
        }

        ec.message.addMessage(`Created Docker container ${appInstance.instanceName} (${appInstance.instanceUuid})${warnings && warnings.length ? ' warnings: ' + JSON.stringify(warnings) : ''}`)
    } else if (restResponse.statusCode == 409) {
        instanceExists = true
        ec.logger.warn(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) conflict [${restResponse.getReasonPhrase()}]:\n${restResponse.text()}`)
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) got a conflict on create [${restResponse.getReasonPhrase()}]`)
    } else if (restResponse.statusCode == 404) {
        // POST /v1.24/images/create?fromImage=busybox&tag=latest HTTP/1.1
        ec.message.addMessage(ec.l10n.localize("Image not Found ,or may be Docker login fail"))
    } else {
        ec.logger.error(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) ERROR [${restResponse.getReasonPhrase()}]:\n${restResponse.text()}`)
        ec.message.addMessage(`Error on create container for ${appInstance.instanceName} (${restResponse.statusCode}): ${restResponse.getReasonPhrase()}`)
    }
} catch (e) {
    connectSuccess = false
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

instanceStarted = false
instanceRunning = null
const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("POST")
dockerUri(restClient, "containers", containerName, "start").build()

try {
    const restResponse = restClient.call()
    if (restResponse.statusCode == 204) {
        instanceStarted = true
        instanceRunning = true
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) started`)
    } else if (restResponse.statusCode == 304) {
        instanceStarted = false
        instanceRunning = true
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) already started`)
    } else if (restResponse.statusCode == 404) {
        instanceStarted = false
        instanceRunning = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) does not exist, init first`)
    } else {
        errorString = restResponse.getReasonPhrase()
        ec.message.addMessage(`Server error on Docker host: ${errorString}`)
    }
} catch (e) {
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

instanceStopped = false
instanceRunning = null
const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("POST")
dockerUri(restClient, "containers", containerName, "stop").build()

try {
    const restResponse = restClient.call()
    if (restResponse.statusCode == 204) {
        instanceStopped = true
        instanceRunning = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) stopped`)
    } else if (restResponse.statusCode == 304) {
        instanceStopped = false
        instanceRunning = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) was not running`)
    } else if (restResponse.statusCode == 404) {
        instanceStopped = false
        instanceRunning = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) does not exist, init first`)
    } else {
        errorString = restResponse.getReasonPhrase()
        ec.message.addMessage(`Server error on Docker host: ${errorString}`)
    }
} catch (e) {
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

instanceRemoved = false
instanceExists = null
const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("DELETE")
dockerUri(restClient, "containers", containerName).build()

try {
    const restResponse = restClient.call()
    if (restResponse.statusCode == 204) {
        instanceRemoved = true
        instanceExists = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) removed`)
    } else if (restResponse.statusCode == 404) {
        instanceRemoved = false
        instanceExists = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) does not exist, init first`)
    } else {
        errorString = restResponse.getReasonPhrase()
        ec.message.addMessage(`Server error on Docker host: ${errorString}`)
    }
} catch (e) {
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

connectSuccess = null
instanceExists = null
instanceRunning = null
statusString = ""
errorString = ""
startedAt = null
finishedAt = null
const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
if (instanceHost == null) { ec.message.addMessage(`No InstanceHost found for AppInstance ${appInstanceId}`); return; }
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("GET")
dockerUri(restClient, "containers", containerName, "json").build()

try {
    const restResponse = restClient.call()
    connectSuccess = true

    if (restResponse.statusCode == 200) {
        instanceExists = true

        inspectMap = restResponse.jsonObject()
        const stateMap = inspectMap.State || {}
        instanceRunning = !!stateMap.Running
        statusString = stateMap.Status == null ? null : String(stateMap.Status)
        errorString = stateMap.Error == null ? null : String(stateMap.Error)
        startedAt = stateMap.StartedAt ? ec.l10n.parseTimestamp(String(stateMap.StartedAt), "") : null
        if (stateMap.FinishedAt) finishedAt = ec.l10n.parseTimestamp(String(stateMap.FinishedAt), "")

        if (!appInstance.instanceUuid) {
            appInstance.instanceUuid = inspectMap.Id
            appInstance.update()
        }

        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) ${instanceRunning ? 'running' : 'NOT running'}, status ${statusString}, ${errorString ? 'error: ' + errorString + ', ' : ''}started at ${ec.l10n.format(startedAt, '')}${finishedAt ? ', finished at ' + ec.l10n.format(finishedAt, '') : ''}`)
    } else if (restResponse.statusCode == 404) {
        instanceExists = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) does not exist`)
    } else {
        errorString = restResponse.getReasonPhrase()
        ec.message.addMessage(`Server error on Docker host: ${errorString}`)
    }
} catch (e) {
    connectSuccess = false
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

instanceLog = null
const appInstance = ec.entity.find("moqui.server.instance.AppInstance").condition("appInstanceId", appInstanceId).one()
const instanceHost = appInstance.findRelatedOne("instanceHost", null, null)
if (instanceHost == null) { ec.message.addMessage(`No InstanceHost found for AppInstance ${appInstanceId}`); return; }
const dockerUri = (restClient, ...paths) => {
    const uri = restClient.uri().protocol(instanceHost.hostProtocol || "http").host(String(instanceHost.hostAddress))
            .port(instanceHost.adminPort ? parseInt(instanceHost.adminPort, 10) : 2375)
    for (const path of paths) uri.path(path)
    return uri
}
const containerName = String(appInstance.instanceUuid || appInstance.instanceName)

const restClient = ec.service.rest().method("GET")
dockerUri(restClient, "containers", containerName, "logs").parameter("stdout", "true").parameter("tail", "50").build()

try {
    const restResponse = restClient.call()
    connectSuccess = true

    if (restResponse.statusCode == 200) {
        instanceExists = true
        // drop the stream frame headers and the terminal color codes
        instanceLog = restResponse.text().replace(/\u0001\u0000{5}[\u0000\u0001][\u003c\ufffd]/g, "").replace(/\u001b\[[0-9]{0,2}m/g, "")
    } else if (restResponse.statusCode == 404) {
        instanceExists = false
        ec.message.addMessage(`Docker container ${appInstance.instanceName} (${appInstance.instanceUuid}) does not exist`)
    } else {
        errorString = restResponse.getReasonPhrase()
        ec.message.addMessage(`Server error on Docker host: ${errorString}`)
    }
} catch (e) {
    connectSuccess = false
    ec.logger.error(`Error connecting to Docker host: ${e}`)
    ec.message.addError(`Error connecting to Docker host: ${e}`)
}

const identifier = (name, what) => {
    if (!/^[A-Za-z0-9_]+$/.test(String(name ?? ""))) throw new Error(`The ${what} name [${name}] is not a plain identifier`)
    return String(name)
}
const quoted = (text) => String(text ?? "").replace(/'/g, "''")
const databaseName = identifier(envMap.entity_ds_database, "database")
const userName = identifier(envMap.entity_ds_user, "user")

dbConnectSuccess = ec.entity.testConfConnection(adminMap)
databaseExists = false
dbUserExists = false
if (!dbConnectSuccess) ec.logger.warn("Test connection to MySQL failed")

if (dbConnectSuccess) {
    const dbCount = ec.entity.runSqlCountConf("information_schema.schemata", `schema_name='${databaseName}'`, adminMap)
    if (dbCount > 0) databaseExists = true

    const userCount = ec.entity.runSqlCountConf("mysql.user", `user='${userName}'`, adminMap)
    if (userCount > 0) dbUserExists = true
}

const identifier = (name, what) => {
    if (!/^[A-Za-z0-9_]+$/.test(String(name ?? ""))) throw new Error(`The ${what} name [${name}] is not a plain identifier`)
    return String(name)
}
const quoted = (text) => String(text ?? "").replace(/'/g, "''")
const databaseName = identifier(envMap.entity_ds_database, "database")
const userName = identifier(envMap.entity_ds_user, "user")

databaseCreated = false
userCreated = false

// see if database exists (SELECT * FROM information_schema.schemata WHERE schema_name='moqui')
const dbCount = ec.entity.runSqlCountConf("information_schema.schemata", `schema_name='${databaseName}'`, adminMap)
if (dbCount > 0) {
    ec.message.addMessage(`Database ${databaseName} already exists on host ${adminMap.entity_ds_host}`)
} else {
    const dbRows = ec.entity.runSqlUpdateConf(`CREATE DATABASE \`${databaseName}\` DEFAULT CHARACTER SET utf8`, adminMap)
    if (dbRows > 0) {
        databaseCreated = true
        ec.message.addMessage(`Created database ${databaseName} on host ${adminMap.entity_ds_host}`)
    }
}

// see if user exists (SELECT * FROM mysql.user WHERE user='root')
const userCount = ec.entity.runSqlCountConf("mysql.user", `user='${userName}'`, adminMap)
if (userCount > 0) {
    ec.message.addMessage(`User ${userName} already exists on host ${envMap.entity_ds_host}`)
} else {
    // NOTE: calling CREATE USER with IF NOT EXISTS returns an error instead of warning in MySQL 5.7.* (at least 5.7.10)
    // NOTE: always seems to return 0 rows updated so ignore
    ec.entity.runSqlUpdateConf(`CREATE USER '${userName}' IDENTIFIED BY '${quoted(envMap.entity_ds_password)}'`, adminMap)
    userCreated = true
    ec.message.addMessage(`Created user ${userName} on host ${adminMap.entity_ds_host}`)
}
// NOTE: because of issue above user must already exist, often the case (using same user to access all tenant DBs; may create separate users to access only a single tenant DB)
ec.entity.runSqlUpdateConf(`GRANT ALL ON ${databaseName}.* TO '${userName}'`, adminMap)

const identifier = (name, what) => {
    if (!/^[A-Za-z0-9_]+$/.test(String(name ?? ""))) throw new Error(`The ${what} name [${name}] is not a plain identifier`)
    return String(name)
}
const quoted = (text) => String(text ?? "").replace(/'/g, "''")
const databaseName = identifier(envMap.entity_ds_database, "database")
const userName = identifier(envMap.entity_ds_user, "user")

dbConnectSuccess = ec.entity.testConfConnection(adminMap)
databaseExists = false
dbUserExists = false
if (!dbConnectSuccess) ec.logger.warn("Test connection to Postgres failed")

if (dbConnectSuccess) {
    const dbCount = ec.entity.runSqlCountConf("pg_database", `pg_database.datname='${databaseName}'`, adminMap)
    if (dbCount > 0) databaseExists = true

    const userCount = ec.entity.runSqlCountConf("pg_catalog.pg_user", `usename='${userName}'`, adminMap)
    if (userCount > 0) dbUserExists = true
}

const identifier = (name, what) => {
    if (!/^[A-Za-z0-9_]+$/.test(String(name ?? ""))) throw new Error(`The ${what} name [${name}] is not a plain identifier`)
    return String(name)
}
const quoted = (text) => String(text ?? "").replace(/'/g, "''")
const databaseName = identifier(envMap.entity_ds_database, "database")
const userName = identifier(envMap.entity_ds_user, "user")

databaseCreated = false
userCreated = false

const dbCount = ec.entity.runSqlCountConf("pg_database", `pg_database.datname='${databaseName}'`, adminMap)
if (dbCount > 0) {
    ec.message.addMessage(`Database ${databaseName} already exists on host ${adminMap.entity_ds_host}`)
} else {
    // Postgres reports no rows for CREATE DATABASE, so a statement that did not fail created it
    ec.entity.runSqlUpdateConf(`CREATE DATABASE ${databaseName}`, adminMap)
    databaseCreated = true
    ec.message.addMessage(`Created database ${databaseName} on host ${adminMap.entity_ds_host}`)
}

const userCount = ec.entity.runSqlCountConf("pg_catalog.pg_user", `usename='${userName}'`, adminMap)
if (userCount > 0) {
    ec.message.addMessage(`User ${userName} already exists on host ${envMap.entity_ds_host}`)
} else {
    ec.entity.runSqlUpdateConf(`CREATE USER ${userName} WITH PASSWORD '${quoted(envMap.entity_ds_password)}'`, adminMap)
    userCreated = true
    ec.message.addMessage(`Created user ${userName} on host ${adminMap.entity_ds_host}`)
}
ec.entity.runSqlUpdateConf(`GRANT ALL PRIVILEGES ON DATABASE ${databaseName} TO ${userName}`, adminMap)
